package com.tripmateai.controller; import com.tripmateai.dto.request.nearby.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.nearby.NearbyPlaceResponse; import com.tripmateai.service.NearbyPlaceService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/destinations/{destinationId}/nearby-places") @RequiredArgsConstructor public class NearbyPlaceController {private final NearbyPlaceService service; @GetMapping public ResponseEntity<ApiResponse<List<NearbyPlaceResponse>>> list(@PathVariable Long destinationId,@RequestParam(required=false) String category){return ResponseUtils.success(service.list(destinationId,category),"Nearby places retrieved");} @GetMapping("/{placeId}") public ResponseEntity<ApiResponse<NearbyPlaceResponse>> get(@PathVariable Long destinationId,@PathVariable Long placeId){return ResponseUtils.success(service.get(destinationId,placeId),"Nearby place retrieved");} @PostMapping public ResponseEntity<ApiResponse<NearbyPlaceResponse>> create(@PathVariable Long destinationId,@Valid @RequestBody CreateNearbyPlaceRequest r){return ResponseUtils.created(service.create(destinationId,r),"Nearby place created");} @PutMapping("/{placeId}") public ResponseEntity<ApiResponse<NearbyPlaceResponse>> update(@PathVariable Long destinationId,@PathVariable Long placeId,@Valid @RequestBody UpdateNearbyPlaceRequest r){return ResponseUtils.success(service.update(destinationId,placeId,r),"Nearby place updated");} @DeleteMapping("/{placeId}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long destinationId,@PathVariable Long placeId){service.delete(destinationId,placeId);return ResponseUtils.success(null,"Nearby place deleted");}}
